# -*- coding: utf-8 -*-
from odoo import models, fields, api

class FreightAirline(models.Model):
    _name = 'freight.airline'
    _description = 'FREIGHT AIRLINE'
    _inherit = ['mail.thread', 'mail.activity.mixin']
    _order = 'id desc'

    name = fields.Char(string="Carrier Name", required=True)
    partner_id = fields.Many2one(comodel_name="res.partner", string="Address", required=True)
    phone = fields.Char(string="Phone")
    fax = fields.Char(string="Fax")
    pic_id = fields.Many2one(comodel_name="res.partner", string="Main PIC")
    child_ids = fields.One2many(comodel_name="res.partner", related="partner_id.child_ids", readonly=True, string="Contact")
    country_id = fields.Many2one(comodel_name="res.country", string="Country")
    active = fields.Boolean(string="Active")
    iata_code = fields.Char(string="IATA Code")
    mawb_prefix = fields.Char(string="MAWB Prefix")
    company_type = fields.Selection(selection=[["person","Individual"],["company","Company"]], string="Company Type")
    important_note = fields.Html(string="Important Note")
    message_is_follower = fields.Boolean(string="Is Follower", readonly=True)
    message_follower_ids = fields.One2many(comodel_name="mail.followers", related="partner_id.message_follower_ids", readonly=True, string="Followers")
    message_partner_ids = fields.Many2many(comodel_name="res.partner", relation="freight_airline_message_partner_ids_rel", column1="freight_airline_id", column2="res_partner_id", string="Followers (Partners)")
    message_ids = fields.One2many(comodel_name="mail.message", related="partner_id.message_ids", readonly=True, string="Messages")
    has_message = fields.Boolean(string="Has Message", readonly=True)
    message_needaction = fields.Boolean(string="Action Needed", readonly=True, help="If checked, new messages require your attention.")
    message_needaction_counter = fields.Integer(string="Number of Actions", readonly=True, help="Number of messages requiring action")
    message_has_error = fields.Boolean(string="Message Delivery error", readonly=True, help="If checked, some messages have a delivery error.")
    message_has_error_counter = fields.Integer(string="Number of errors", readonly=True, help="Number of messages with delivery error")
    message_attachment_count = fields.Integer(string="Attachment Count", readonly=True)
    message_main_attachment_id = fields.Many2one(comodel_name="ir.attachment", string="Main Attachment")
    website_message_ids = fields.One2many(comodel_name="mail.message", related="partner_id.website_message_ids", readonly=True, string="Website Messages")
    message_has_sms_error = fields.Boolean(string="SMS Delivery error", readonly=True, help="If checked, some messages have a delivery error.")
    email_normalized = fields.Char(string="Normalized Email", readonly=True, help="This field is used to search on email address as the primary email field can contain more than strictly an email address.")
    is_blacklisted = fields.Boolean(string="Blacklist", readonly=True, help="If the email address is on the blacklist, the contact won't receive mass mailing anymore, from any list")
    message_bounce = fields.Integer(string="Bounce", help="Counter of the number of bounced emails for this contact")
    activity_ids = fields.One2many(comodel_name="mail.activity", related="partner_id.activity_ids", readonly=True, string="Activities")
    activity_state = fields.Selection(selection=[["overdue","Overdue"],["today","Today"],["planned","Planned"]], string="Activity State", readonly=True, help="Status based on activities\nOverdue: Due date is already passed\nToday: Activity date is today\nPlanned: Future activities.")
    activity_user_id = fields.Many2one(comodel_name="res.users", string="Responsible User")
    activity_type_id = fields.Many2one(comodel_name="mail.activity.type", string="Next Activity Type")
    activity_type_icon = fields.Char(string="Activity Type Icon", readonly=True, help="Font awesome icon e.g. fa-tasks")
    activity_date_deadline = fields.Date(string="Next Activity Deadline", readonly=True)
    my_activity_date_deadline = fields.Date(string="My Activity Deadline", readonly=True)
    activity_summary = fields.Char(string="Next Activity Summary")
    activity_exception_decoration = fields.Selection(selection=[["warning","Alert"],["danger","Error"]], string="Activity Exception Decoration", readonly=True, help="Type of the exception activity on record.")
    activity_exception_icon = fields.Char(string="Icon", readonly=True, help="Icon to indicate an exception activity.")
    activity_calendar_event_id = fields.Many2one(comodel_name="calendar.event", string="Next Activity Calendar Event", readonly=True)
    image_1920 = fields.Binary(string="Image")
    image_1024 = fields.Binary(string="Image 1024", readonly=True)
    image_512 = fields.Binary(string="Image 512", readonly=True)
    image_256 = fields.Binary(string="Image 256", readonly=True)
    image_128 = fields.Binary(string="Image 128", readonly=True)
    avatar_1920 = fields.Binary(string="Avatar", readonly=True)
    avatar_1024 = fields.Binary(string="Avatar 1024", readonly=True)
    avatar_512 = fields.Binary(string="Avatar 512", readonly=True)
    avatar_256 = fields.Binary(string="Avatar 256", readonly=True)
    avatar_128 = fields.Binary(string="Avatar 128", readonly=True)
    translated_display_name = fields.Char(string="Translated Display Name", readonly=True)
    date = fields.Date(string="Date")
    title = fields.Many2one(comodel_name="res.partner.title", string="Title")
    parent_id = fields.Many2one(comodel_name="res.partner", string="Related Company")
    parent_name = fields.Char(string="Parent name", readonly=True)
    ref = fields.Char(string="Code")
    lang = fields.Selection(selection=[["en_US","English (US)"],["vi_VN","Vietnamese / Tiếng Việt"]], string="Language", help="All the emails and documents sent to this contact will be translated in this language.")
    active_lang_count = fields.Integer(string="Active Lang Count", readonly=True)
